#!/usr/bin/env node
// Generate platform theme code from an app's DTCG tokens (ENGINEERING_STANDARD §6A). Zero dependencies.
//   node build.mjs [--design design]
// Reads  design/tokens/{primitive,base,semantic.light,semantic.dark}.json, design/tokens/presets/*.json,
//        design/icons.json, and optional design/tokens.config.json:
//        { "platforms": ["css","tailwind","ts","dart","swift"], "out": { "dart": "lib/core/design/generated" } }
// Writes generated files (never hand-edit them). Run validate.mjs first; build refuses unresolved refs.
import { writeFileSync, mkdirSync, existsSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { load, resolveAll, loadTokens, rgba, camel, kebab } from './lib.mjs'

const args = Object.fromEntries(process.argv.slice(2).reduce((a, v, i, all) =>
  (v.startsWith('--') ? [...a, [v.slice(2), all[i + 1]]] : a), []))
const designDir = resolve(args.design || 'design')
const cfgPath = join(designDir, 'tokens.config.json')
const cfg = existsSync(cfgPath) ? load(cfgPath) : {}
const platforms = cfg.platforms || ['css', 'tailwind', 'ts', 'dart', 'swift']
const outDir = (p) => resolve(cfg.out?.[p] || join(designDir, 'build', p))
const HEADER = 'GENERATED by engineering-standard/design-tokens/build.mjs from design/tokens — DO NOT EDIT.'

const errors = []
const t = loadTokens(join(designDir, 'tokens'), ['light', 'dark'])
if (t.missing.length) { console.error(`✗ missing ${t.missing.join(', ')}`); process.exit(1) }

// themes: light, dark, and each preset → { 'color.surface.base': '#FFFFFF', ... } (semantic colours only)
const resolveTheme = (sem, label) => {
  const r = resolveAll({ ...t.primitive, ...t.base, ...sem }, label, (e) => errors.push(e))
  return Object.fromEntries(Object.keys(sem).sort().map(k => [k, r[k]]))
}
const themes = { light: resolveTheme(t.modes.light, 'light'), dark: resolveTheme(t.modes.dark, 'dark') }
for (const [name, p] of Object.entries(t.presets)) themes[name] = resolveTheme(p.tokens, `preset:${name}`)
const base = resolveAll({ ...t.primitive, ...t.base }, 'base', (e) => errors.push(e))
const baseKeys = Object.keys(t.base).sort()
const baseType = (k) => t.base[k].type
const icons = existsSync(join(designDir, 'icons.json')) ? load(join(designDir, 'icons.json')).icons || {} : {}
if (errors.length) { errors.forEach(e => console.error(`✗ ${e}`)); process.exit(1) }

const colorKeys = Object.keys(themes.light)
const num = (v) => parseFloat(String(v))
const field = (k) => camel(k.split('.').slice(1))            // color.status.onDanger → statusOnDanger
const cssVar = (k) => `--${k.split('.').map(kebab).join('-')}` // → --color-status-on-danger
const write = (p, file, body) => { const d = outDir(p); mkdirSync(d, { recursive: true }); writeFileSync(join(d, file), body); console.log(`  ${p.padEnd(9)} ${join(d, file)}`) }

// ── CSS custom properties ─────────────────────────────────────────────────────
function css() {
  const block = (sel, theme) => `${sel} {\n${colorKeys.map(k => `  ${cssVar(k)}: ${theme[k]};`).join('\n')}\n}`
  const baseBlock = `:root {\n${baseKeys.map(k => `  ${cssVar(k)}: ${base[k]};`).join('\n')}\n}`
  const presets = Object.keys(themes).filter(n => n !== 'light' && n !== 'dark')
  write('css', 'tokens.css', `/* ${HEADER}\n   Theme switch: set <html data-theme="light|dark|<preset>">; no attribute = follow the OS. */\n` +
    [baseBlock,
     block(':root, [data-theme="light"]', themes.light),
     block('[data-theme="dark"]', themes.dark),
     `@media (prefers-color-scheme: dark) {\n${block(':root:not([data-theme])', themes.dark).replace(/^/gm, '  ')}\n}`,
     ...presets.map(n => block(`[data-theme="${n}"]`, themes[n]))].join('\n\n') + '\n')
}

// ── Tailwind v3 preset (classes resolve to the CSS vars, so theme switching needs no rebuild) ──
function tailwind() {
  const nest = (keys, strip, val) => keys.reduce((o, k) => {
    const parts = k.split('.').slice(strip).map(kebab); let d = o
    parts.slice(0, -1).forEach(p => { d = d[p] = d[p] || {} }); d[parts.at(-1)] = val(k); return o
  }, {})
  const pick = (prefix) => baseKeys.filter(k => k.startsWith(prefix))
  const preset = {
    theme: {
      // Replace (not extend) colours/spacing/radius/fontSize so default palette classes like bg-red-500 don't exist.
      colors: { transparent: 'transparent', current: 'currentColor', ...nest(colorKeys, 1, k => `var(${cssVar(k)})`) },
      spacing: nest(pick('space.'), 1, k => `var(${cssVar(k)})`),
      borderRadius: nest(pick('radius.'), 1, k => `var(${cssVar(k)})`),
      fontSize: nest(pick('font.size.'), 2, k => `var(${cssVar(k)})`),
      fontFamily: nest(pick('font.family.'), 2, k => [`var(${cssVar(k)})`]),
      fontWeight: nest(pick('font.weight.'), 2, k => String(base[k])),
      screens: Object.fromEntries(pick('breakpoint.').filter(k => num(base[k]) > 0).map(k => [k.split('.')[1], base[k]])),
    },
  }
  write('tailwind', 'preset.cjs', `// ${HEADER}\n// tailwind.config: presets: [require('./design/build/tailwind/preset.cjs')] and import design/build/css/tokens.css once.\nmodule.exports = ${JSON.stringify(preset, null, 2)}\n`)
}

// ── TypeScript values (charts/canvas/email need raw values) + icon registry ──
function ts() {
  const obj = (th) => `{\n${colorKeys.map(k => `    ${JSON.stringify(k.slice(6))}: ${JSON.stringify(th[k])},`).join('\n')}\n  }`
  write('ts', 'tokens.ts', `// ${HEADER}\nexport const themes = {\n${Object.entries(themes).map(([n, th]) => `  ${JSON.stringify(n)}: ${obj(th)},`).join('\n')}\n} as const\n` +
    `export type ThemeName = keyof typeof themes\nexport type ColorToken = keyof typeof themes.light\n` +
    `export const base = ${JSON.stringify(Object.fromEntries(baseKeys.map(k => [k, base[k]])), null, 2)} as const\n` +
    `/** Prefer CSS vars in components; use this only where CSS can't reach (canvas, charts, emails). */\nexport const cssVar = (token: ColorToken) => \`var(--color-\${token.replace(/\\./g, '-').replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase()})\`\n`)
  const names = Object.entries(icons).filter(([, v]) => v.lucide)
  const glyphs = [...new Set(names.map(([, v]) => v.lucide))].sort()
  write('ts', 'icons.tsx', `// ${HEADER}\n// The ONLY file allowed to import the icon package (lint: std.web.icons-direct).\nimport { ${glyphs.join(', ')} } from 'lucide-react'\n` +
    `import type { LucideProps } from 'lucide-react'\n\nexport const icons = {\n${names.map(([n, v]) => `  ${JSON.stringify(n)}: ${v.lucide},`).join('\n')}\n} as const\nexport type IconName = keyof typeof icons\n\n` +
    `const sizes = { sm: 'var(--icon-size-sm)', md: 'var(--icon-size-md)', lg: 'var(--icon-size-lg)', xl: 'var(--icon-size-xl)' } as const\n` +
    `export function Icon({ name, size = 'md', label, ...rest }: { name: IconName; size?: keyof typeof sizes; label?: string } & Omit<LucideProps, 'size'>) {\n` +
    `  const C = icons[name]\n  return <C width={sizes[size]} height={sizes[size]} aria-hidden={label ? undefined : true} aria-label={label} role={label ? 'img' : undefined} {...rest} />\n}\n`)
}

// ── Flutter: ThemeExtension with every semantic colour + const scales + icon registry ──
function dart() {
  const argb = (hex) => { const c = rgba(hex); return `Color(0x${c.alphaHex}${c.hex6})` }
  const fields = colorKeys.map(field)
  const inst = (th) => `AppColors(\n${colorKeys.map(k => `    ${field(k)}: ${argb(th[k])},`).join('\n')}\n  )`
  const scale = (cls, prefix, fmt) => {
    const ks = baseKeys.filter(k => k.startsWith(prefix)); if (!ks.length) return ''
    return `abstract final class ${cls} {\n${ks.map(k => `  static const ${fmt(k)};`).join('\n')}\n}\n`
  }
  const leaf = (k, strip) => camel(k.split('.').slice(strip))
  const dartStr = (s) => `'${String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`
  write('dart', 'app_tokens.dart', `// ${HEADER}\n// The ONLY Dart file allowed to write colour literals (lint: std.dart.raw-color).\n// ignore_for_file: lines_longer_than_80_chars\nimport 'package:flutter/material.dart';\n\n` +
    `/// Semantic colours. Screens read \`context.colors.statusDanger\`, never a literal.\n@immutable\nclass AppColors extends ThemeExtension<AppColors> {\n` +
    `  const AppColors({\n${fields.map(f => `    required this.${f},`).join('\n')}\n  });\n\n${fields.map(f => `  final Color ${f};`).join('\n')}\n\n` +
    Object.entries(themes).map(([n, th]) => `  static const ${camel(n.split(/[-_]/))} = ${inst(th)};`).join('\n\n') + '\n\n' +
    `  static const Map<String, AppColors> all = {${Object.keys(themes).map(n => `'${n}': ${camel(n.split(/[-_]/))}`).join(', ')}};\n\n` +
    `  @override\n  AppColors copyWith({${fields.map(f => `Color? ${f}`).join(', ')}}) => AppColors(\n${fields.map(f => `        ${f}: ${f} ?? this.${f},`).join('\n')}\n      );\n\n` +
    `  @override\n  AppColors lerp(ThemeExtension<AppColors>? other, double t) {\n    if (other is! AppColors) return this;\n    return AppColors(\n${fields.map(f => `      ${f}: Color.lerp(${f}, other.${f}, t)!,`).join('\n')}\n    );\n  }\n}\n\n` +
    `extension AppColorsX on BuildContext {\n  AppColors get colors => Theme.of(this).extension<AppColors>()!;\n}\n\n` +
    scale('AppSpace', 'space.', k => `double ${leaf(k, 1)} = ${num(base[k])}`) +
    scale('AppRadius', 'radius.', k => `double ${leaf(k, 1)} = ${num(base[k])}`) +
    scale('AppFontSize', 'font.size.', k => `double ${leaf(k, 2)} = ${num(base[k])}`) +
    scale('AppFontWeight', 'font.weight.', k => `FontWeight ${leaf(k, 2)} = FontWeight.w${base[k]}`) +
    scale('AppFontFamily', 'font.family.', k => `String ${leaf(k, 2)} = ${dartStr(String(base[k]).split(',')[0].trim())}`) +
    scale('AppLineHeight', 'font.lineHeight.', k => `double ${leaf(k, 2)} = ${num(base[k])}`) +
    scale('AppIconSize', 'icon.size.', k => `double ${leaf(k, 2)} = ${num(base[k])}`) +
    scale('AppElevation', 'elevation.', k => `double ${leaf(k, 1)} = ${num(base[k])}`) +
    scale('AppMotion', 'motion.duration.', k => `Duration ${leaf(k, 2)} = Duration(milliseconds: ${num(base[k])})`) +
    scale('AppBreakpoint', 'breakpoint.', k => `double ${leaf(k, 1)} = ${num(base[k])}`))
  const named = Object.entries(icons).filter(([, v]) => v.material)
  write('dart', 'app_icons.dart', `// ${HEADER}\n// The ONLY Dart file allowed to reference Icons.* (lint: std.dart.icons-direct).\nimport 'package:flutter/material.dart';\n\n` +
    `abstract final class AppIcons {\n${named.map(([n, v]) => `  static const IconData ${camel(n.split('.'))} = Icons.${v.material};`).join('\n')}\n\n` +
    `  static const Map<String, IconData> byName = {\n${named.map(([n]) => `    '${n}': ${camel(n.split('.'))},`).join('\n')}\n  };\n}\n`)
}

// ── SwiftUI ───────────────────────────────────────────────────────────────────
function swift() {
  const col = (hex) => { const c = rgba(hex); return `Color(hex: 0x${c.hex6}, alpha: ${(c.a).toFixed(3)})` }
  const fields = colorKeys.map(field)
  const leaf = (k, strip) => camel(k.split('.').slice(strip))
  const scale = (name, prefix, strip, type, fmt = (v) => num(v)) => {
    const ks = baseKeys.filter(k => k.startsWith(prefix)); if (!ks.length) return ''
    return `public enum ${name} {\n${ks.map(k => `    public static let ${leaf(k, strip)}: ${type} = ${fmt(base[k])}`).join('\n')}\n}\n\n`
  }
  write('swift', 'AppTokens.swift', `// ${HEADER}\n// The ONLY Swift file allowed to construct colours (lint: std.swift.raw-color).\nimport SwiftUI\n\n` +
    `public struct AppColors: Sendable {\n${fields.map(f => `    public let ${f}: Color`).join('\n')}\n\n` +
    Object.entries(themes).map(([n, th]) => `    public static let ${camel(n.split(/[-_]/))} = AppColors(\n${colorKeys.map((k, i) => `        ${field(k)}: ${col(th[k])}${i < colorKeys.length - 1 ? ',' : ''}`).join('\n')}\n    )`).join('\n\n') +
    `\n\n    public static func forScheme(_ scheme: ColorScheme) -> AppColors { scheme == .dark ? dark : light }\n}\n\n` +
    `private extension Color {\n    init(hex: UInt32, alpha: Double) {\n        self.init(.sRGB, red: Double((hex >> 16) & 0xFF) / 255, green: Double((hex >> 8) & 0xFF) / 255, blue: Double(hex & 0xFF) / 255, opacity: alpha)\n    }\n}\n\n` +
    scale('AppSpace', 'space.', 1, 'CGFloat') + scale('AppRadius', 'radius.', 1, 'CGFloat') +
    scale('AppFontSize', 'font.size.', 2, 'CGFloat') + scale('AppIconSize', 'icon.size.', 2, 'CGFloat') +
    scale('AppMotion', 'motion.duration.', 2, 'Double', v => num(v) / 1000) +
    scale('AppBreakpoint', 'breakpoint.', 1, 'CGFloat'))
  const named = Object.entries(icons).filter(([, v]) => v.sf)
  write('swift', 'AppIcons.swift', `// ${HEADER}\n// The ONLY Swift file allowed to call Image(systemName:) (lint: std.swift.icons-direct).\nimport SwiftUI\n\n` +
    `public enum AppIcon {\n${named.map(([n, v]) => `    public static let ${camel(n.split('.'))} = Image(systemName: "${v.sf}")`).join('\n')}\n}\n`)
}

const emit = { css, tailwind, ts, dart, swift }
console.log(`Building tokens from ${designDir}: ${Object.keys(themes).join(', ')} → ${platforms.join(', ')}`)
for (const p of platforms) { if (!emit[p]) { console.error(`✗ unknown platform ${p}`); process.exit(1) } emit[p]() }
